    12  static struct RProc*
    13  create_proc_from_string(mrb_state *mrb, const char *s, mrb_int len, mrb_value binding, const char *file, mrb_int line)
    14  {
    15    mrbc_context *cxt;
    16    struct mrb_parser_state *p;
    17    struct RProc *proc;
    18    const struct RProc *scope;
    19    struct REnv *e;
    20    mrb_callinfo *ci; /* callinfo of eval caller */
    21    struct RClass *target_class = NULL;
    22    struct mrb_context *c = mrb->c;
    23
    24    if (!mrb_nil_p(binding)) {
    25      mrb_value scope_obj;
    26      if (!mrb_class_defined_id(mrb, MRB_SYM(Binding))
    27          || !mrb_obj_is_kind_of(mrb, binding, mrb_class_get_id(mrb, MRB_SYM(Binding)))) {
    28        mrb_raisef(mrb, E_TYPE_ERROR, "wrong argument type %C (expected binding)",
    29            mrb_obj_class(mrb, binding));
    30      }
    31      scope_obj = mrb_iv_get(mrb, binding, MRB_SYM(proc));
    32      mrb_check_type(mrb, scope_obj, MRB_TT_PROC);
    33      scope = mrb_proc_ptr(scope_obj);
    34      if (MRB_PROC_CFUNC_P(scope)) {
    35        e = NULL;
    36      }
    37      else {
    38        mrb_value env = mrb_iv_get(mrb, binding, MRB_SYM(env));
    39        mrb_check_type(mrb, env, MRB_TT_ENV);
    40        e = (struct REnv *)mrb_obj_ptr(env);
    41        mrb_assert(e != NULL);
    42      }
    43    }
    44    else {
    45      ci = (c->ci > c->cibase) ? c->ci - 1 : c->cibase;
    46      scope = ci->proc;
    47      e = NULL;
    48    }
    49
    50    if (file) {
    51      if (strlen(file) >= UINT16_MAX) {
    52        mrb_raise(mrb, E_ARGUMENT_ERROR, "filename too long");
    53      }
    54    }
    55    else {
    56      file = "(eval)";
    57    }
    58
    59    cxt = mrbc_context_new(mrb);
    60    cxt->lineno = (uint16_t)line;
    61
    62    mrbc_filename(mrb, cxt, file);
    63    cxt->capture_errors = TRUE;
    64    cxt->no_optimize = TRUE;
    65    cxt->upper = scope && MRB_PROC_CFUNC_P(scope) ? NULL : scope;
    66
    67    p = mrb_parse_nstring(mrb, s, len, cxt);
    68
    69    /* only occur when memory ran out */
    70    if (!p) {
    71      mrbc_context_free(mrb, cxt);
    72      mrb_raise(mrb, E_RUNTIME_ERROR, "Failed to create parser state (out of memory)");
    73    }
    74
    75    if (0 < p->nerr) {
    76      /* parse error */
    77      mrb_value str;
    78
    79      mrbc_context_free(mrb, cxt);
    80      if (!p->error_buffer[0].message) {
    81        mrb_parser_free(p);
    82        mrb_raise(mrb, E_SYNTAX_ERROR, "compile error");
    83      }
    84      if (file) {
    85        str = mrb_format(mrb, "file %s line %d: %s",
    86                         file,
    87                         p->error_buffer[0].lineno,
    88                         p->error_buffer[0].message);
    89      }
    90      else {
    91        str = mrb_format(mrb, "line %d: %s",
    92                         p->error_buffer[0].lineno,
    93                         p->error_buffer[0].message);
    94      }
    95      mrb_parser_free(p);
    96      mrb_exc_raise(mrb, mrb_exc_new_str(mrb, E_SYNTAX_ERROR, str));
    97    }
    98
    99    proc = mrb_generate_code(mrb, p);
   100    if (proc == NULL) {
   101      /* codegen error */
   102      mrb_parser_free(p);
   103      mrbc_context_free(mrb, cxt);
   104      mrb_raise(mrb, E_SCRIPT_ERROR, "codegen error");
   105    }
   106    if (c->ci > c->cibase) {
   107      ci = &c->ci[-1];
   108    }
   109    else {
   110      ci = c->cibase;
   111    }
   112    if (scope) {
   113      target_class = MRB_PROC_TARGET_CLASS(scope);
   114      if (!MRB_PROC_CFUNC_P(scope)) {
   115        if (e == NULL) {
   116          /* when `binding` is nil */
   117          e = mrb_vm_ci_env(ci);
   118          if (e == NULL) {
   119            e = mrb_env_new(mrb, c, ci, ci->proc->body.irep->nlocals, ci->stack, target_class);
   120            ci->u.env = e;
   121          }
   122        }
   123        proc->e.env = e;
   124        proc->flags |= MRB_PROC_ENVSET;
   125        mrb_field_write_barrier(mrb, (struct RBasic*)proc, (struct RBasic*)e);
   126      }
   127    }
   128    proc->upper = scope;
   129    mrb_vm_ci_target_class_set(mrb->c->ci, target_class);
   130    /* mrb_codedump_all(mrb, proc); */
   131
   132    mrb_parser_free(p);
   133    mrbc_context_free(mrb, cxt);
   134
   135    return proc;
   136  }
