   139  exec_irep(mrb_state *mrb, mrb_value self, struct RProc *proc)
   140  {
   141    /* no argument passed from eval() */
   142    mrb->c->ci->n = 0;
   143    mrb->c->ci->nk = 0;
   144    /* clear block */
   145    mrb->c->ci->stack[1] = mrb_nil_value();
   146    return mrb_exec_irep(mrb, self, proc);
   147  }
