   151  {
   152    const char *s;
   153    mrb_int len;
   154    mrb_value binding = mrb_nil_value();
   155    const char *file = NULL;
   156    mrb_int line = 1;
   157    struct RProc *proc;
   158
   159    mrb_get_args(mrb, "s|ozi", &s, &len, &binding, &file, &line);
   160
   161    proc = create_proc_from_string(mrb, s, len, binding, file, line);
